pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // Ensure the two addresses differ so that a change is observable.
        vm.assume(caller != newOwner);
        // Make sure the initial owner (this contract's setUp or constructor) is different from caller
        // so the call by a non-owner is non-trivial.
        vm.assume(caller != c.owner());
        // Record the current owner before the call.
        address prevOwner = c.owner();
        // Let any caller (not necessarily the current owner) attempt to set the owner.
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            // The call succeeded (no revert).
            // For the reference contract, the call must have been made by the current owner;
            // otherwise it would have reverted. Therefore, if it succeeded and the caller is not
            // the previous owner, we have a bug.
            // The assertion we make: if caller is not the previous owner, the owner must NOT change.
            // This is the general rule that the reference satisfies (a non-owner call reverts, which
            // we won't reach here) and the mutant violates (it succeeds and changes the owner).
            // We encode this as: owner should remain prevOwner when caller != prevOwner.
            bool ownerUnchanged = (c.owner() == prevOwner);
            if (caller != prevOwner) {
                assertTrue(ownerUnchanged, "non-owner should not change owner");
            }
            // If caller is the owner, the owner may or may not change; we don't constrain that.
        } catch {
            // The call reverted. In the reference contract, this happens when caller != owner,
            // so the owner must remain unchanged. The mutant never reverts; if we are testing
            // the mutant and it reverted, something else is wrong, but our property focuses on
            // the success case. We just ensure that on revert the owner is unchanged (reference rule).
            assertTrue(c.owner() == prevOwner, "owner changed on revert");
        }
    }
}

