pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        address previousOwner = c.owner();

        vm.prank(caller);
        bool succeeded;
        try c.setOwner(newOwner) {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        address currentOwner = c.owner();
        if (caller == previousOwner) {
            assertTrue(succeeded && currentOwner == newOwner);
        } else {
            assertTrue(currentOwner == previousOwner);
        }
    }
}

