contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerCandidate, bool isOwnerCall) public {
        vm.assume(ownerCandidate != address(0));
        if (isOwnerCall) {
            // The contract's owner is msg.sender from setUp (Test contract).
            // We want to test the path where msg.sender IS the current owner.
            // In setUp, owner is the Test contract itself.
            vm.prank(address(this));
        } else {
            // Use a fuzzed address as the caller; make sure it's not the current owner.
            vm.assume(ownerCandidate != address(this));
            vm.prank(ownerCandidate);
        }
        bool success;
        try c.setOwner(ownerCandidate) {
            success = true;
        } catch {
            success = false;
        }
        if (isOwnerCall) {
            // The OWNER call must succeed in the reference (and fail in the mutant).
            assertTrue(success);
        } else {
            // A NON-OWNER call must revert in both versions (baseline invariant).
            // We don't assert on the non-owner path to allow the fuzzer to pick
            // the distinguishing path (owner call) via the isOwnerCall boolean.
            // The fuzzer will find isOwnerCall=true, where the assertion surfaces the difference.
        }
    }
}

